import{U as e,W as t,j as n,nt as r}from"./chunks/framework.HOVv_sfg.js";var i=JSON.parse(`{"title":"Early Music","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"pages/earlymusic.md","filePath":"pages/earlymusic.md"}`),a={name:`pages/earlymusic.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="early-music" tabindex="-1">Early Music <a class="header-anchor" href="#early-music" aria-label="Permalink to “Early Music”">​</a></h1><p>Early music encompasses the musical traditions of the Medieval, Renaissance, and Baroque periods, as well as the repertories and performance practices associated with them.</p><p>This section explores composers, works, instruments, recordings, and historical performance practices from the Middle Ages to the eighteenth century.</p><h2 id="periods" tabindex="-1">Periods <a class="header-anchor" href="#periods" aria-label="Permalink to “Periods”">​</a></h2><h3 id="medieval" tabindex="-1">Medieval <a class="header-anchor" href="#medieval" aria-label="Permalink to “Medieval”">​</a></h3><p>Music from the Middle Ages, including sacred and secular repertories from the early medieval period through the fifteenth century.</p><ul><li>Composers</li><li>Works</li><li>Repertories</li><li>Manuscripts</li></ul><h3 id="renaissance" tabindex="-1">Renaissance <a class="header-anchor" href="#renaissance" aria-label="Permalink to “Renaissance”">​</a></h3><p>The musical traditions of the fifteenth and sixteenth centuries, including sacred polyphony, secular song, and instrumental music.</p><ul><li>Composers</li><li>Works</li><li>Repertories</li><li>Instruments</li></ul><h3 id="baroque" tabindex="-1">Baroque <a class="header-anchor" href="#baroque" aria-label="Permalink to “Baroque”">​</a></h3><p>Music of the seventeenth and eighteenth centuries, including opera, concerto, sonata, chamber music, and sacred music.</p><ul><li>Composers</li><li>Works</li><li>Instruments</li><li>Performance practice</li></ul><h2 id="composers" tabindex="-1">Composers <a class="header-anchor" href="#composers" aria-label="Permalink to “Composers”">​</a></h2><p>A selection of composers represented in the collection.</p><ul><li>Antonio Vivaldi</li><li>Georg Philipp Telemann</li><li>Wolfgang Amadeus Mozart</li><li>George Frideric Handel</li><li>Johann Sebastian Bach</li></ul><h2 id="instruments" tabindex="-1">Instruments <a class="header-anchor" href="#instruments" aria-label="Permalink to “Instruments”">​</a></h2><p>Historical instruments and their repertories.</p><ul><li>Viola da gamba</li><li>Theorbo</li><li>Lute</li><li>Harpsichord</li><li>Traverso</li><li>Baroque violin</li><li>Cornett</li><li>Dulcian</li></ul><h2 id="performance-practice" tabindex="-1">Performance Practice <a class="header-anchor" href="#performance-practice" aria-label="Permalink to “Performance Practice”">​</a></h2><p>Topics related to historical performance and interpretation.</p><ul><li>Historically informed performance</li><li>Historical tuning</li><li>Temperament</li><li>Ornamentation</li><li>Improvisation</li><li>Historical instruments</li></ul><h2 id="recordings" tabindex="-1">Recordings <a class="header-anchor" href="#recordings" aria-label="Permalink to “Recordings”">​</a></h2><p>Selected recordings and performances of early music.</p><p>Explore recordings by composer, work, ensemble, performer, instrument, period, and label.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><p>Research notes, listening notes, and other material related to early music.</p>`,27)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};